const inputItem = $input.first();
const rawText = inputItem.json.data || '';

const lines = rawText.split('\n').filter((l) => l.trim().length > 0);

const records = [];
let parseFailures = 0;
for (const line of lines) {
  try {
    records.push(JSON.parse(line));
  } catch (e) {
    parseFailures++;
  }
}

const STOPWORDS = new Set(['this','that','with','from','have','were','been','their','about','which','would','could','there','where','when','what','your','http','https','and','the','for','are','was']);

function significantWords(text) {
  return new Set(
    String(text || '')
      .toLowerCase()
      .replace(/[^a-z0-9\s]/g, ' ')
      .split(/\s+/)
      .filter((w) => w.length > 3 && !STOPWORDS.has(w))
  );
}

function jaccard(setA, setB) {
  if (setA.size === 0 || setB.size === 0) return 0;
  let intersection = 0;
  for (const w of setA) if (setB.has(w)) intersection++;
  const union = setA.size + setB.size - intersection;
  return union === 0 ? 0 : intersection / union;
}

const PLACEHOLDER_CATEGORY = 'unclassified — pending ai extraction';

const enrichedInputs = records.map((r, idx) => {
  const fullRecord = r.full_record || {};
  const factors = fullRecord.ai_extracted_factors || {};
  const rawCategory = String(r.category || '').trim().toLowerCase();
  // A record still carrying UOR-02's literal "not yet categorized" placeholder
  // has no real category information -- treat it as uncategorized (empty),
  // never as matching another record that also happens to be uncategorized,
  // and never let the placeholder's own words ("unclassified", "pending",
  // "extraction") leak into the topical-similarity word bag.
  const category = rawCategory === PLACEHOLDER_CATEGORY ? '' : rawCategory;
  return {
    idx,
    opportunity_id: r.opportunity_id ?? null,
    source_type: r.source_type ?? null,
    source_name: r.source ?? null,
    category,
    title: r.raw_signal?.opportunity_title || '',
    normalized_opportunity: r.normalized_opportunity || '',
    source_url: r.source_url ?? null,
    date_discovered: r.date_discovered ?? null,
    is_synthetic: r.evidence?.is_synthetic === true,
    evidence_source_missing: r.evidence?.evidence_source_missing,
    base_confidence: typeof r.evidence_confidence === 'number' ? r.evidence_confidence : 0,
    sample_size_carried: typeof factors.evidence_sample_size?.estimate === 'number' ? factors.evidence_sample_size.estimate : null,
    words: significantWords(`${category} ${r.raw_signal?.opportunity_title || ''} ${r.normalized_opportunity || ''}`),
  };
});

const byId = new Map();
enrichedInputs.forEach((e) => {
  const key = e.opportunity_id ?? `__no_id_${e.idx}`;
  if (!byId.has(key)) byId.set(key, []);
  byId.get(key).push(e);
});

const urlToIds = new Map();
enrichedInputs.forEach((e) => {
  const url = (e.source_url || '').trim();
  if (!url || url.toUpperCase() === 'N/A') return;
  if (!urlToIds.has(url)) urlToIds.set(url, new Set());
  urlToIds.get(url).add(e.opportunity_id);
});

function daysSince(dateStr) {
  if (!dateStr) return null;
  const t = Date.parse(dateStr);
  if (Number.isNaN(t)) return null;
  return (Date.now() - t) / 86400000;
}

function recencyScore(days) {
  if (days === null) return 0;
  if (days <= 7) return 10;
  if (days <= 30) return 7;
  if (days <= 90) return 4;
  if (days <= 365) return 2;
  return 0;
}

const SIMILARITY_THRESHOLD = 0.25;

const results = enrichedInputs.map((e) => {
  const group = byId.get(e.opportunity_id ?? `__no_id_${e.idx}`);
  const sameIdOthers = group.filter((g) => g.idx !== e.idx);
  const distinctSourceNamesInGroup = new Set(group.map((g) => g.source_name));

  let corroboration_status;
  let diversity_score;
  let corroborating_ids = [];

  if (sameIdOthers.length > 0) {
    if (distinctSourceNamesInGroup.size > 1) {
      corroboration_status = 'MULTI_SOURCE_CORROBORATED';
      diversity_score = 10;
    } else {
      corroboration_status = 'SINGLE_SOURCE_REPEAT_ONLY';
      diversity_score = 0;
    }
    corroborating_ids = [e.opportunity_id];
  } else {
    let bestMatch = null;
    let bestScore = 0;
    for (const other of enrichedInputs) {
      if (other.idx === e.idx) continue;
      if (other.opportunity_id === e.opportunity_id) continue;
      if (!other.category || other.category !== e.category) continue;
      const sim = jaccard(e.words, other.words);
      if (sim >= SIMILARITY_THRESHOLD && sim > bestScore) {
        bestScore = sim;
        bestMatch = other;
      }
    }
    if (bestMatch) {
      corroborating_ids = [bestMatch.opportunity_id];
      if (bestMatch.source_name !== e.source_name) {
        corroboration_status = 'RELATED_SIGNAL_FOUND_DIFFERENT_SOURCE';
        diversity_score = 6;
      } else {
        corroboration_status = 'RELATED_SIGNAL_FOUND_SAME_SOURCE';
        diversity_score = 2;
      }
    } else {
      corroboration_status = 'NO_COMPARABLE_RECORDS_FOUND';
      diversity_score = 0;
    }
  }

  const manipulatedIds = e.source_url && urlToIds.has(e.source_url.trim()) ? urlToIds.get(e.source_url.trim()) : new Set();
  const manipulation_flag = manipulatedIds.size > 1;
  const manipulation_reason = manipulation_flag
    ? `source_url shared across ${manipulatedIds.size} distinct opportunity_ids: ${[...manipulatedIds].join(', ')}`
    : null;

  const low_content_flag = (e.title.trim().length + e.normalized_opportunity.trim().length) < 15;

  const days = daysSince(e.date_discovered);
  const recency = recencyScore(days);

  const primary_source_score =
    e.evidence_source_missing === false &&
    typeof e.source_url === 'string' &&
    /^https?:\/\//i.test(e.source_url)
      ? 10
      : 0;

  let enriched =
    0.5 * e.base_confidence +
    0.2 * (recency * 10) +
    0.2 * (diversity_score * 10) +
    0.1 * (primary_source_score * 10);
  enriched = Math.round(enriched);

  if (e.is_synthetic) {
    enriched = 0;
  } else if (manipulation_flag) {
    enriched = Math.min(enriched, 30);
  }
  enriched = Math.max(0, Math.min(100, enriched));

  let status;
  if (e.is_synthetic) status = 'SYNTHETIC_TEST_ONLY';
  else if (manipulation_flag) status = 'MANIPULATION_SUSPECTED';
  else status = 'ENRICHED_MULTI_FACTOR';

  return {
    opportunity_id: e.opportunity_id,
    source_type: e.source_type,
    source_name: e.source_name,
    date_discovered: e.date_discovered,
    days_since_discovery: days === null ? null : Math.round(days * 10) / 10,
    base_confidence: e.base_confidence,
    recency_score: recency,
    diversity_score,
    primary_source_score,
    sample_size_carried: e.sample_size_carried,
    manipulation_flag,
    manipulation_reason,
    low_content_flag,
    corroboration_status,
    corroborating_opportunity_ids: corroborating_ids,
    evidence_confidence_v2: enriched,
    evidence_confidence_v2_status: status,
    evidence_confidence_formula_version: 'uor03-v1-cross-reference-2026-09-04',
    computed_at: new Date().toISOString(),
  };
});

const fileText = results.map((r) => JSON.stringify(r)).join('\n') + '\n';

return [{
  json: {
    record_count: results.length,
    parse_failures: parseFailures,
    file_text: fileText,
  },
}];
